"""Script, caption, CTA models."""

from __future__ import annotations

from pydantic import BaseModel, Field


class ScriptPackage(BaseModel):
    """Full content package generated by AI for one video."""

    hook: str = Field(..., description="Câu mở đầu (3–8 giây đầu)")
    body: str = Field(..., description="Nội dung chính / USP")
    cta: str = Field(..., description="Call-to-action cuối video")
    full_script: str = Field(..., description="Script voiceover đầy đủ")
    caption: str = Field(..., description="Caption đăng TikTok")
    hashtags: list[str] = Field(default_factory=list)
    title: str = Field(default="", description="Title ngắn (nếu cần)")
    keywords: list[str] = Field(default_factory=list)

    def voiceover_text(self) -> str:
        """Text gửi sang TTS (đã nối sẵn)."""
        return self.full_script.strip()
